files.content:
.root {
  --vt-surface: #FFFFFF;
  --vt-surface-2: #F9F9F9;
  --vt-surface-deep: #000000;
  --vt-ink: #000000;
  --vt-ink-soft: #717275;
  --vt-on-deep: #FFFFFF;
  --vt-accent: #247cff;
  --vt-on-accent: #000000;
  --vt-accent-ink: #565758;
  --vt-accent-on-deep: #247cff;
  --vt-line: #eaeaea;

  font-family: 'Open Sans', sans-serif;
  background: var(--vt-surface);
  color: var(--vt-ink);
  scroll-behavior: smooth;
}

/* Navigation */
.nav {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 1030;
  background: var(--vt-surface);
  box-shadow: 0 0.5rem 1rem rgba(0, 0, 0, 0.08);
  padding: 20px 0;
}

.navIn {
  display: flex;
  align-items: center;
  justify-content: space-between;
  max-width: 1320px;
  margin: 0 auto;
  padding: 0 1rem;
}

.logo {
  text-decoration: none;
  display: inline-block;
}

.brand {
  display: flex;
  flex-direction: column;
  align-items: center;
  color: var(--vt-accent);
  font-weight: 700;
  font-size: 1.5rem;
  line-height: 1.2;
}

.brand strong {
  color: var(--vt-ink-soft);
  font-size: 0.75rem;
  font-weight: 600;
}

.navLinks {
  display: flex;
  gap: 1.5rem;
}

.navLinks a {
  color: var(--vt-ink-soft);
  text-decoration: none;
  font-weight: 600;
  font-size: 16px;
  padding: 15px 0;
  transition: color 0.3s;
}

.navLinks a:hover,
.navLinks a:focus {
  color: var(--vt-ink);
}

/* Hero */
.hero {
  padding-top: 94px;
}

.heroContainer {
  position: relative;
  height: 580px;
  overflow: hidden;
}

.heroImage {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.heroText {
  position: absolute;
  bottom: 0;
  right: 0;
  width: 50%;
  background: var(--vt-surface);
  padding: 1.5rem 2.5rem;
  z-index: 2;
}

.heroText h1 {
  font-size: 48px;
  font-weight: 700;
  margin-top: auto;
  margin-bottom: 0.5rem;
}

.heroText h1 span {
  color: var(--vt-accent);
}

.heroText p {
  color: var(--vt-ink-soft);
  margin-bottom: 1.5rem;
}

.heroLinks {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
}

.customLink {
  display: inline-block;
  border: 1px solid var(--vt-line);
  color: var(--vt-accent);
  font-weight: 600;
  line-height: 40px;
  padding: 0 30px;
  text-transform: uppercase;
  text-decoration: none;
  margin-right: 1.5rem;
  transition: background 0.3s, color 0.3s;
}

.customLink:hover {
  background: var(--vt-line);
  color: var(--vt-accent);
}

.contactPhone {
  font-weight: 600;
  color: var(--vt-ink-soft);
}

/* About */
.about {
  padding: 7rem 0;
}

.aboutInner {
  max-width: 1320px;
  margin: 0 auto;
  padding: 0 1rem;
  display: flex;
  flex-wrap: wrap;
  align-items: center;
}

.aboutInner h2 {
  font-size: 36px;
  font-weight: 700;
  margin-bottom: 1rem;
}

.aboutInner p {
  color: var(--vt-ink-soft);
  font-size: 18px;
  line-height: 1.6;
}

/* Gallery */
.gallery {
  padding: 0;
}

.galleryRow {
  display: flex;
  gap: 0;
  max-width: 1320px;
  margin: 0 auto;
  padding: 0 1rem;
}

.galleryItem {
  flex: 1;
  overflow: hidden;
}

.galleryImage {
  width: 100%;
  height: auto;
  display: block;
}

/* Timeline */
.timelineSection {
  padding: 7rem 0;
}

.timelineTitle {
  text-align: center;
  font-size: 36px;
  font-weight: 700;
  margin-bottom: 3rem;
}

.timeline {
  position: relative;
  max-width: 900px;
  margin: 0 auto;
  padding: 0 1rem;
}

.timeline::before {
  content: "";
  position: absolute;
  top: 37px;
  left: 50%;
  bottom: 0;
  width: 0;
  border-left: 1px solid var(--vt-line);
  transform: translateX(-50%);
}

.timelineNode {
  position: relative;
  margin-bottom: 2rem;
  min-height: 100px;
}

.timelineNode.odd .timelineContent {
  margin-left: auto;
  text-align: right;
}

.timelineNode.even .timelineContent {
  margin-right: auto;
  text-align: left;
}

.timelineContent {
  width: 50%;
  background: var(--vt-surface);
  border-radius: 0.25rem;
  box-shadow: 0 0.5rem 1rem rgba(0, 0, 0, 0.08);
  padding: 0;
  position: relative;
}

.timelineContent h3 {
  background: var(--vt-surface-deep);
  color: var(--vt-on-deep);
  padding: 0.75rem 1.5rem;
  border-radius: 0.25rem 0.25rem 0 0;
  margin: 0;
  font-size: 1.5rem;
  font-weight: 600;
}

.timelineContent p {
  padding: 1rem 1.5rem;
  color: var(--vt-ink-soft);
  margin: 0;
}

.timelineIcon {
  position: absolute;
  left: 50%;
  top: 0;
  transform: translateX(-50%);
  width: 80px;
  height: 80px;
  border-radius: 50%;
  background: var(--vt-surface);
  box-shadow: 0 1rem 3rem rgba(0, 0, 0, 0.175);
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 10;
}

.iconDot {
  display: block;
  width: 24px;
  height: 24px;
  background: var(--vt-accent);
  border-radius: 50%;
}

.timelineNode.odd .timelineContent h3::after {
  content: "";
  position: absolute;
  top: 50%;
  left: 0;
  transform: translate(-100%, -50%);
  border-right: 10px solid var(--vt-surface-deep);
  border-top: 10px solid transparent;
  border-bottom: 10px solid transparent;
}

.timelineNode.even .timelineContent h3::after {
  content: "";
  position: absolute;
  top: 50%;
  right: 0;
  transform: translate(100%, -50%);
  border-left: 10px solid var(--vt-surface-deep);
  border-top: 10px solid transparent;
  border-bottom: 10px solid transparent;
}

/* Footer */
.footer {
  background: var(--vt-surface-2);
  padding: 5rem 0;
}

.footerRow {
  display: flex;
  flex-wrap: wrap;
  max-width: 1320px;
  margin: 0 auto;
  padding: 0 1rem;
  gap: 2rem;
}

.footerCol {
  flex: 1 1 30%;
}

.footerCol h5 {
  font-size: 1.25rem;
  font-weight: 700;
  margin-bottom: 1.5rem;
}

.footerCol p,
.footerCol a {
  color: var(--vt-ink-soft);
}

.footerCol a:hover {
  color: var(--vt-accent);
}

.copyright {
  text-align: center;
  margin-top: 3rem;
  color: var(--vt-ink-soft);
  font-size: 14px;
}

.copyright a {
  color: var(--vt-accent);
}

/* Focus styles */
.root a:focus-visible,
.root button:focus-visible {
  outline: 2px solid var(--vt-accent);
  outline-offset: 2px;
}

/* Responsive */
@media screen and (max-width: 991px) {
  .heroText {
    position: relative;
    bottom: auto;
    left: auto;
    width: auto;
    margin-bottom: -100px;
    padding: 2rem;
  }
  .heroContainer {
    height: inherit;
  }
  .heroText h1 {
    font-size: 38px;
  }
  .aboutInner h2 {
    font-size: 32px;
  }
  .timelineTitle {
    font-size: 32px;
  }
  .timeline::before {
    top: 37px;
  }
  .timelineNode.odd .timelineContent,
  .timelineNode.even .timelineContent {
    width: 50%;
    margin: 0;
  }
  .timelineNode.odd .timelineContent {
    margin-left: auto;
  }
  .timelineNode.even .timelineContent {
    margin-right: auto;
  }
}

@media screen and (max-width: 767px) {
  .navIn {
    flex-direction: column;
    gap: 0.5rem;
  }
  .navLinks {
    flex-wrap: wrap;
    justify-content: center;
  }
  .hero {
    padding-top: 74px;
  }
  .heroText h1 {
    font-size: 32px;
  }
  .aboutInner h2 {
    font-size: 28px;
  }
  .timelineTitle {
    font-size: 28px;
  }
  .timeline::before {
    left: 33px;
    top: 60px;
    transform: none;
  }
  .timelineNode {
    margin-left: 60px;
  }
  .timelineNode.odd .timelineContent,
  .timelineNode.even .timelineContent {
    width: 100%;
    margin: 0;
    text-align: left;
  }
  .timelineIcon {
    left: 0;
    transform: none;
  }
  .timelineNode.odd .timelineContent h3::after,
  .timelineNode.even .timelineContent h3::after {
    display: none;
  }
  .footerRow {
    flex-direction: column;
  }
  .footerCol {
    flex: 1 1 auto;
  }
}

@media screen and (max-width: 480px) {
  .heroText {
    padding: 1rem;
  }
  .heroLinks .customLink {
    font-size: 12px;
    line-height: 30px;
    margin-right: 12px;
    padding: 0 25px;
  }
  .contactPhone {
    font-size: 12px;
  }
}
